-- The 108 owner-approved blessings (see migration 20261015002000_blessings.sql).
-- Idempotent: re-running updates text/timing/order and keeps ids stable.
on conflict (id) do update set text = excluded.text, scripture_ref = excluded.scripture_ref, theme = excluded.theme,
  kind = excluded.kind, youtube_id = excluded.youtube_id, passage_id = excluded.passage_id, play_from = excluded.play_from,
  quality = excluded.quality, sort = excluded.sort, status = 'published';
